from fastapi import FastAPI, Request, Depends, HTTPException
from fastapi.responses import JSONResponse

app = FastAPI()

class ConsultationLockedError(Exception):
    def __init__(self, consultation_id: str):
        self.consultation_id = consultation_id

@app.exception_handler(ConsultationLockedError)
async def consultation_locked_handler(request: Request, exc: ConsultationLockedError):
    return JSONResponse(
        status_code=423,
        content={
            "detail": f"Consultation record {exc.consultation_id} is currently locked by attending physician"
        }
    )

@app.post("/ehr/consultations/{consultation_id}/lock")
async def lock_clinical_consultation(
    consultation_id: str,
    ehr_service: EHRService = Depends(get_ehr_service),
    clinician: Clinician = Depends(get_authenticated_clinician)
):
    session = await ehr_service.lookup_consultation(consultation_id)
    if not session:
        raise HTTPException(status_code=404, detail="Consultation not found")
    if not await ehr_service.can_access_patient(clinician.id, session.patient_id):
        raise HTTPException(status_code=403, detail="Forbidden: clinician is not authorized to access this patient's records")

    if session.is_locked:
        raise ConsultationLockedError(consultation_id)

    await ehr_service.acquire_lock(consultation_id, clinician.id)
    return {"status": "locked", "consultation_id": consultation_id}
